"""Locally authored SVG technical illustrations; no remote rendering dependencies."""
from html import escape
from pathlib import Path

ART = {}
INK='#172f40'; MUTED='#506879'; TEAL='#087e80'; RED='#b94343'; BLUE='#405fb1'; GOLD='#ac7919'


def text(x,y,value,size=20,color=INK,weight=400):
    return f'<text x="{x}" y="{y}" fill="{color}" font-size="{size}" font-weight="{weight}">{escape(str(value))}</text>'


def box(x,y,w,h,title,lines=(),color=TEAL,server=False):
    result=f'<rect x="{x}" y="{y}" width="{w}" height="{h}" rx="16" fill="#ffffff" stroke="{color}" stroke-width="2"/>'
    result+=f'<rect x="{x}" y="{y+16}" width="5" height="{h-32}" fill="{color}"/>'
    result+=text(x+20,y+35,title,23,color,700)
    for i,line in enumerate(lines):result+=text(x+20,y+66+i*27,line,18,MUTED)
    if server:
        for i in range(3):
            result+=f'<rect x="{x+w-55}" y="{y+18+i*15}" width="34" height="10" rx="3" fill="{color}" opacity=".20"/><circle cx="{x+w-28}" cy="{y+23+i*15}" r="2" fill="{color}"/>'
    return result


def arrow(points,label='',lx=0,ly=0,color=TEAL,dashed=False):
    return f'<polyline points="{points}" fill="none" stroke="{color}" stroke-width="3" stroke-dasharray="{ "7 6" if dashed else "none"}" marker-end="url(#arrow)"/>'+ (text(lx,ly,label,18,color,600) if label else '')


def add(key,title,subtitle,body,caption):
    ART[key]={'title':title,'caption':caption,'svg':f'''<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1100 650" role="img" aria-labelledby="title desc"><title id="title">{escape(title)}</title><desc id="desc">{escape(caption)}</desc><defs><marker id="arrow" markerWidth="9" markerHeight="9" refX="8" refY="4.5" orient="auto-start-reverse"><path d="M0,0 L9,4.5 L0,9" fill="context-stroke"/></marker><pattern id="grid" width="22" height="22" patternUnits="userSpaceOnUse"><circle cx="1" cy="1" r="1" fill="#d8e1e7"/></pattern></defs><rect width="1100" height="650" rx="24" fill="#f3f7f8"/><rect x="20" y="125" width="1060" height="485" fill="url(#grid)"/><g font-family="Segoe UI,Arial,sans-serif">{text(38,55,title,32,INK,700)}{text(38,91,subtitle,19,MUTED)}{body}{text(38,625,'Том V · учебная схема · связи и размеры показаны условно',16,MUTED)}</g></svg>'''}


