def write_assets(directory):
    directory.mkdir(exist_ok=True)
    for key,data in ART.items():
        (directory/(key+'.svg')).write_text(data['svg'],encoding='utf-8')


def figure(key):
    d=ART[key]
    return f'<figure class="book-figure"><div class="figure-scroll"><img src="assets/{key}.svg" alt="{escape(d["caption"])}" loading="lazy" width="1100" height="650"></div><figcaption><strong>{escape(d["title"])}</strong>. {escape(d["caption"])} <a href="assets/{key}.svg">Открыть схему крупно</a></figcaption></figure>'
